import itertools, json
Aopts=['KNR','MNP','LMQ','LNR','MNR']
Bopts=['KLN','NPR','PQR','KMP','LPQ']
Adays=[{2,6},{1,4,7},{6,7},{3,5},{1,6}]
Bdays=[{4,7},{2},{3,7},{4,5},{3,5,8}]
As=[x for x in itertools.product(*Aopts) if len(set(x))==5]
Bs=[x for x in itertools.product(*Bopts) if len(set(x))==5]
counts={}
witness={}
for a in As:
 for b in Bs:
  both=set(a)&set(b)
  if len(both)!=3 or len(both & set('KQR'))!=1: continue
  days={p:set() for p in 'KLMNPQR'}
  for p,d in zip(a,Adays): days[p].update(d)
  for p,d in zip(b,Bdays): days[p].update(d)
  n=sum(len(d)>=3 for d in days.values())
  counts[n]=counts.get(n,0)+1
  witness.setdefault(n,{'A':''.join(a),'B':''.join(b)})
lo,hi=min(counts),max(counts)
print(json.dumps({'feasible_linkages':sum(counts.values()),'bounds':[lo,hi],'low_witness':witness[lo],'high_witness':witness[hi],'decision':'confirmed' if lo>=3 else 'excluded' if hi<3 else 'undetermined'}))
print('distribution',counts)
for n in [lo,hi]:
 w=witness[n]; ds={p:set() for p in 'KLMNPQR'}
 for p,d in zip(w['A'],Adays): ds[p]|=d
 for p,d in zip(w['B'],Bdays): ds[p]|=d
 print(n, {p:sorted(d) for p,d in ds.items()})

